<!doctype html>
<html><head><meta charset="utf-8"><title>Homeo-Hall financial report</title>
<style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#1d1d1f;font-size:11px;line-height:1.5}h1{font-size:24px;margin:0 0 4px}h2{font-size:13px;margin:22px 0 8px}p{margin:0;color:#555}.header{border-bottom:1px solid #e0e0e0;padding-bottom:14px;margin-bottom:18px}.brand{color:#0066cc;font-weight:bold;font-size:11px;letter-spacing:1px}.range{text-align:right;color:#7a7a7a}.grid{width:100%;border-collapse:separate;border-spacing:8px;margin:0 -8px}.grid td{width:33%;background:#fafafc;padding:11px;border:1px solid #e0e0e0}.grid small{display:block;color:#7a7a7a;margin-bottom:4px}.grid strong{font-size:16px}.notes{background:#f5f5f7;padding:10px;margin-top:18px;color:#555}.signature{margin-top:52px;border-top:1px solid #999;width:220px;padding-top:5px;color:#7a7a7a}</style></head>
<body><div class="header"><span class="brand">HOMEO-HALL</span><h1>Financial report</h1><p>{{ \Illuminate\Support\Carbon::parse($range['from'])->format('d M Y') }} – {{ \Illuminate\Support\Carbon::parse($range['to'])->format('d M Y') }}</p></div>
<table class="grid"><tr><td><small>Sales revenue</small><strong>৳{{ number_format($summary['sales'], 2) }}</strong></td><td><small>Purchases</small><strong>৳{{ number_format($summary['purchases'], 2) }}</strong></td><td><small>COGS</small><strong>৳{{ number_format($summary['cogs'], 2) }}</strong></td></tr><tr><td><small>Gross profit</small><strong>৳{{ number_format($summary['gross_profit'], 2) }}</strong></td><td><small>Other expenses</small><strong>৳{{ number_format($summary['expenses'], 2) }}</strong></td><td><small>Net operating profit</small><strong>৳{{ number_format($summary['net_profit'], 2) }}</strong></td></tr><tr><td><small>Sales records</small><strong>{{ $summary['sales_count'] }}</strong></td><td><small>Units sold</small><strong>{{ $summary['units_sold'] }}</strong></td><td><small>Closing inventory value</small><strong>৳{{ number_format($summary['inventory_value'], 2) }}</strong></td></tr></table>
<p class="notes">Purchases are inventory acquisitions and are not treated as operating expenses. Gross profit = sales revenue − historical COGS. Net operating profit = gross profit − other operating expenses. Inventory is valued at weighted-average cost.</p><p class="signature">Prepared by chamber administrator</p>
</body></html>
